import{_ as a,o as i,c as t,a0 as l}from"./chunks/framework.Bmhw_dvp.js";const m=JSON.parse('{"title":"Features","description":"","frontmatter":{},"headers":[],"relativePath":"features/index.md","filePath":"features/index.md"}'),n={name:"features/index.md"};function o(r,e,s,u,d,c){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><p>Cloud Mail is packed with features for a complete email experience — all running on Cloudflare&#39;s edge network.</p><h2 id="💰-low-cost" tabindex="-1">💰 Low Cost <a class="header-anchor" href="#💰-low-cost" aria-label="Permalink to &quot;💰 Low Cost&quot;">​</a></h2><p>No server required. Deploy to Cloudflare Workers to dramatically reduce hosting costs. The free tier covers most small deployments.</p><h2 id="💻-responsive-design" tabindex="-1">💻 Responsive Design <a class="header-anchor" href="#💻-responsive-design" aria-label="Permalink to &quot;💻 Responsive Design&quot;">​</a></h2><p>Automatically adapts to desktop and mobile browsers. Built with Vue 3 and Element Plus UI framework.</p><h2 id="📧-email-sending" tabindex="-1">📧 Email Sending <a class="header-anchor" href="#📧-email-sending" aria-label="Permalink to &quot;📧 Email Sending&quot;">​</a></h2><p>Integrated with Resend for reliable email delivery:</p><ul><li>Bulk email sending</li><li>Inline images in emails</li><li>Attachments</li><li>Send status tracking</li></ul><h2 id="📊-data-visualization" tabindex="-1">📊 Data Visualization <a class="header-anchor" href="#📊-data-visualization" aria-label="Permalink to &quot;📊 Data Visualization&quot;">​</a></h2><p>Powered by ECharts to visualize:</p><ul><li>System usage details</li><li>Email growth over time</li><li>User statistics</li></ul><h2 id="🛡️-admin-features" tabindex="-1">🛡️ Admin Features <a class="header-anchor" href="#🛡️-admin-features" aria-label="Permalink to &quot;🛡️ Admin Features&quot;">​</a></h2><p>Full administrative control:</p><ul><li>User management</li><li>Email management</li><li>RBAC (Role-Based Access Control)</li><li>Resource usage limits</li><li>Feature permissions</li></ul><h2 id="📦-attachment-handling" tabindex="-1">📦 Attachment Handling <a class="header-anchor" href="#📦-attachment-handling" aria-label="Permalink to &quot;📦 Attachment Handling&quot;">​</a></h2><p>Send and receive attachments:</p><ul><li>Stored in Cloudflare R2 object storage</li><li>Download via secure links</li><li>Supports multiple file types</li></ul><h2 id="🔔-email-push-notifications" tabindex="-1">🔔 Email Push Notifications <a class="header-anchor" href="#🔔-email-push-notifications" aria-label="Permalink to &quot;🔔 Email Push Notifications&quot;">​</a></h2><p>Receive email notifications via:</p><ul><li><strong>Telegram bot</strong></li><li>Third-party email forwarding</li></ul><h2 id="📡-open-api" tabindex="-1">📡 Open API <a class="header-anchor" href="#📡-open-api" aria-label="Permalink to &quot;📡 Open API&quot;">​</a></h2><p>Programmatic access with REST API:</p><ul><li>Batch user creation</li><li>Multi-condition email queries</li><li>Full API documentation</li></ul><h2 id="🔢-captcha-recognition" tabindex="-1">🔢 CAPTCHA Recognition <a class="header-anchor" href="#🔢-captcha-recognition" aria-label="Permalink to &quot;🔢 CAPTCHA Recognition&quot;">​</a></h2><p>Uses <strong>Workers AI</strong> to automatically recognize verification codes in received emails.</p><h2 id="🎨-customization" tabindex="-1">🎨 Customization <a class="header-anchor" href="#🎨-customization" aria-label="Permalink to &quot;🎨 Customization&quot;">​</a></h2><p>Personalize your email service:</p><ul><li>Custom website title</li><li>Custom login background image</li><li>Transparency settings</li></ul><h2 id="🤖-turnstile-captcha" tabindex="-1">🤖 Turnstile CAPTCHA <a class="header-anchor" href="#🤖-turnstile-captcha" aria-label="Permalink to &quot;🤖 Turnstile CAPTCHA&quot;">​</a></h2><p>Integrated Cloudflare Turnstile to prevent automated/bot registrations.</p><h2 id="🌐-internationalization-i18n" tabindex="-1">🌐 Internationalization (i18n) <a class="header-anchor" href="#🌐-internationalization-i18n" aria-label="Permalink to &quot;🌐 Internationalization (i18n)&quot;">​</a></h2><p>Multi-language support built-in.</p><h2 id="🚀-more-coming" tabindex="-1">🚀 More Coming <a class="header-anchor" href="#🚀-more-coming" aria-label="Permalink to &quot;🚀 More Coming&quot;">​</a></h2><p>The project is actively developed with more features on the roadmap.</p>',35)])])}const p=a(n,[["render",o]]);export{m as __pageData,p as default};
